    /* Every number in the manual worth a question. */
    numbers: [
      { title: 'Feet', rows: [
        { k: '12 inches', v: 'The most your car may be from the curb when parked.' },
        { k: '10 inches', v: 'At least this far between you and the steering wheel airbag.' },
        { k: '4 feet', v: 'The least room you leave when you pass a bicycle.' },
        { k: '8 feet', v: 'Less than this on at least one side of your car: increase your following distance.' },
        { k: '10 feet', v: 'Stop at least this far from a school bus with its red lights flashing.' },
        { k: '15 feet', v: 'No parking this close to a fire hydrant.' },
        { k: '20 feet', v: 'No parking this close to a crosswalk at an intersection, or to a fire station driveway.' },
        { k: '30 feet', v: 'No parking this close to a stop sign, yield sign or flashing signal.' },
        { k: '50 feet', v: 'No parking this close to the nearest rail of a railroad crossing.' },
        { k: '100 feet', v: 'Signal this far before a turn under 35 mph. No passing this close to an intersection, railroad crossing, bridge or tunnel.' },
        { k: '250 feet', v: 'About how far low beams light the road.' },
        { k: '300 feet', v: 'Signal this far before a turn at 35 mph or more. Low beams when you follow a vehicle this closely.' },
        { k: '500 feet', v: 'Low beams when an oncoming vehicle is this close. Stay this far behind an emergency vehicle. U-turn only if other drivers are at least this far away.' },
        { k: '1,000 feet', v: 'Headlights on when you cannot see this far ahead.' },
        { k: '400 and 600 feet', v: 'Stopping distance from 65 mph: a car, and a loaded truck.' },
      ] },
      { title: 'Seconds', rows: [
        { k: '4 seconds', v: 'Following distance on a dry road. Also behind trucks and motorcycles.' },
        { k: '5 or 6 seconds', v: 'Following distance on wet roads.' },
        { k: '3 to 4 seconds', v: 'Signal this long before a turn.' },
        { k: '12 to 15 seconds', v: 'How far ahead you look: one block in the city, 1/4 mile on a highway.' },
        { k: '6, 8, 9 seconds', v: 'Gap to cross a 30 mph street, to turn right, to turn left onto a major street.' },
        { k: '10 to 15 minutes', v: 'The start of a rainstorm, when the road is most slippery.' },
      ] },
      { title: 'Speed', rows: [
        { k: '70 mph', v: 'The maximum speed limit in Pennsylvania.' },
        { k: '15 mph', v: 'School zone, when the lights flash or at the posted times.' },
        { k: '25 mph', v: 'Or less: a vehicle with the orange triangle. Also: above this, steering around a hazard beats braking.' },
        { k: '35 mph', v: 'Hydroplaning can start here. The signal rule changes here (100 feet below, 300 feet at or above). Top speed with a person in an open truck bed.' },
        { k: '40 mph', v: 'Slower than this on a limited access highway: four-way flashers on.' },
        { k: '45 mph', v: 'The fastest you should drive on a dark road with low beams.' },
        { k: '5 to 10 mph', v: 'Drive this much slower on wet roads. On packed snow: half speed.' },
        { k: '26 mph over', v: 'Under 18: a 90-day suspension for driving this much over the limit.' },
      ] },
      { title: 'Alcohol', rows: [
        { k: '.02', v: 'Under 21: this is DUI. Also the limit for school bus drivers.' },
        { k: '.08', v: 'DUI at 21 or older.' },
        { k: '.04', v: 'Half the adult limit, and already 2 to 7 times more likely to crash.' },
        { k: '.10 and .16', v: 'Where the "High" and "Highest" penalty levels start.' },
        { k: 'One drink', v: '1.5 oz of 80-proof liquor = 12 oz of beer = 5 oz of wine.' },
        { k: '1 hour', v: 'What the body needs to process one drink. Only time works.' },
        { k: '21', v: 'The minimum drinking age.' },
        { k: '1 year', v: 'Suspension for refusing a chemical test. Also for a first DUI under 21.' },
      ] },
      { title: 'Points, suspensions and fines', rows: [
        { k: '6 points', v: 'PennDOT takes action. Under 18: a 90-day suspension.' },
        { k: '3 points', v: 'Come off for every 12 months without a violation. Also what speeding in a school zone costs.' },
        { k: '5 points + 60 days', v: 'Passing a school bus with red lights flashing, plus a fine.' },
        { k: '30 days', v: 'Suspension for driving around or through a railroad gate.' },
        { k: '90 days', v: 'First suspension under 18. Also for a false ID or underage drinking.' },
        { k: '$25', v: 'Extra fine in a work zone without headlights. Also the base fine for no headlights with wipers on.' },
        { k: '$50', v: 'Fine for texting while driving.' },
        { k: '$500', v: 'Fine for a false ID. Also the fine for fleeing police, with a one-year suspension.' },
        { k: 'Doubled', v: 'Fines for certain violations in active work zones, including speeding.' },
      ] },
      { title: 'Permit and licence', rows: [
        { k: '21 or older', v: 'Your supervising driver. Or a parent, guardian or spouse 18 or older with a licence. In the front seat.' },
        { k: '65 hours', v: 'Practice before the road test under 18: 10 at night, 5 in bad weather.' },
        { k: '6 months', v: 'Wait with the permit before the road test, under 18.' },
        { k: '11 PM to 5 AM', v: 'No driving on a junior licence.' },
        { k: '1, then 3', v: 'Passengers under 18 who are not family: one for the first six months, then up to three.' },
        { k: '15 days', v: 'Tell PennDOT about a new address or name within this time.' },
        { k: '12 months', v: 'How often a vehicle needs a safety inspection.' },
        { k: 'Under 4, 4 to 7', v: 'Child seat, then booster seat. Under 2: rear-facing.' },
      ] },
    ],

